  {
    label: 'Expansion',
    color: INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.EXPANSION,
    fontWeight: 'bold',
  },
  {
    label: 'Sustain',
    color: INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.SUSTAIN,
    fontWeight: 'bold',
  },
  {
    label: 'Tail',
    color: INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.TAIL,
    fontWeight: 'bold',
  },
];
